  const rhelNvidiaGuide = ["rhel-nvidia-driver-gaming", "Driver NVIDIA para RHEL e compatíveis", "Roteiro conservador para RHEL, Rocky e AlmaLinux: a disponibilidade do driver depende de release, kernel, subscrição e método documentado pelo fornecedor.", "advanced", "rhel", "https://docs.nvidia.com/datacenter/tesla/driver-installation-guide/", [[1, "Registrar release, kernel e GPU", "Documente o ambiente antes de buscar um pacote ou repositório compatível.", "cat /etc/os-release && uname -r && lspci -k -d ::03xx", "Não instale um pacote Fedora ou um arquivo .run sem compatibilidade declarada para sua release RHEL."], [2, "Consultar o guia NVIDIA e a política da distribuição", "A documentação do fornecedor descreve os pré-requisitos; a distribuição controla repositórios, assinaturas e suporte de kernel.", null, "RHEL, Rocky e AlmaLinux podem ter políticas e fontes de pacote diferentes."], [3, "Validar após o método compatível", "Depois da instalação documentada e do reinício quando aplicável, registre driver e Vulkan.", "nvidia-smi && vulkaninfo --summary", "Se o módulo não carregar, revise o kernel e os logs antes de qualquer tentativa de downgrade."]]];
  const rhelDistribution = distroBySlug.get(rhelNvidiaGuide[4]);
  await connection.execute("INSERT INTO setup_guides (slug, title, description, difficulty, guideVersion, distributionId, status, provenance, sourceId, sourceUrl) VALUES (?, ?, ?, ?, '1.1', ?, 'published', 'community', ?, ?) ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), distributionId = VALUES(distributionId), status = 'published', sourceUrl = VALUES(sourceUrl)", [rhelNvidiaGuide[0], rhelNvidiaGuide[1], rhelNvidiaGuide[2], rhelNvidiaGuide[3], rhelDistribution?.id || null, source.id, rhelNvidiaGuide[5]]);
  const [[rhelNvidiaCurrent]] = await connection.execute("SELECT id FROM setup_guides WHERE slug = ? LIMIT 1", [rhelNvidiaGuide[0]]);
